"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["6745"],{5293(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Smart contract","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/smart-contract/how-it-works","label":"How it works","docId":"smart-contract/how-it-works","unlisted":false},{"type":"link","href":"/docs/smart-contract/functions","label":"Functions by role","docId":"smart-contract/functions","unlisted":false},{"type":"link","href":"/docs/smart-contract/deployments","label":"Deployments","docId":"smart-contract/deployments","unlisted":false}],"href":"/docs/category/smart-contract"},{"type":"link","href":"/docs/glossary","label":"Glossary","docId":"glossary","unlisted":false},{"type":"category","label":"Tutorial","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/tutorial/start","label":"User manual","docId":"tutorial/start","unlisted":false}],"href":"/docs/category/tutorial"},{"type":"category","label":"Market ","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/market/Global","label":"Global","docId":"market/Global","unlisted":false},{"type":"link","href":"/docs/market/Israel","label":"Israel","docId":"market/Israel","unlisted":false},{"type":"link","href":"/docs/market/UK","label":"United Kingdom","docId":"market/UK","unlisted":false},{"type":"link","href":"/docs/market/US","label":"United States","docId":"market/US","unlisted":false},{"type":"link","href":"/docs/market/Europe","label":"Europe and other Geneva Convention countries","docId":"market/Europe","unlisted":false},{"type":"link","href":"/docs/market/Singapore","label":"Singapore","docId":"market/Singapore","unlisted":false},{"type":"link","href":"/docs/market/China","label":"China","docId":"market/China","unlisted":false},{"type":"link","href":"/docs/market/Japan","label":"Japan","docId":"market/Japan","unlisted":false},{"type":"link","href":"/docs/market/Hong-Kong-Taiwan-Korea","label":"Hong Kong, Taiwan and South Korea","docId":"market/Hong-Kong-Taiwan-Korea","unlisted":false},{"type":"link","href":"/docs/market/India","label":"India","docId":"market/India","unlisted":false},{"type":"link","href":"/docs/market/Latin-America","label":"Latin America","docId":"market/Latin-America","unlisted":false},{"type":"link","href":"/docs/market/Middle-East","label":"Middle East","docId":"market/Middle-East","unlisted":false}],"href":"/docs/category/market-"}]},"docs":{"glossary":{"id":"glossary","title":"Glossary","description":"Wikipedia: Negotiable instrument","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Our project is focused on developing electronic payment instruments that, as a matter of law, constitute bills of exchange (bank cheque), leveraging modern technologies such as distributed ledgers (DLT) and smart contract.","sidebar":"tutorialSidebar"},"market/China":{"id":"market/China","title":"China","description":"China operates the world\'s largest infrastructure for electronic commercial drafts. It is a single state-supervised registry, not a blockchain; the central bank\'s own blockchain prototype of 2016\u20132017 was not put into production.","sidebar":"tutorialSidebar"},"market/Europe":{"id":"market/Europe","title":"Europe and other Geneva Convention countries","description":"Continental Europe, Ukraine and most of the former Soviet Union follow the Geneva Uniform Law on Bills of Exchange and Promissory Notes of 1930. Under it a bill must name its payee (Article 1) and cannot be drawn payable to bearer, and the signed paper is the instrument. Two consequences follow for everything on this page it began with the Geneva model and moved to English law because a fungible token cannot satisfy the Geneva form (see Global). The comparisons below therefore show not where our bills fall short of Geneva law, but why they were designed outside it.","sidebar":"tutorialSidebar"},"market/Global":{"id":"market/Global","title":"Global","description":"Electronic bills of exchange","sidebar":"tutorialSidebar"},"market/Hong-Kong-Taiwan-Korea":{"id":"market/Hong-Kong-Taiwan-Korea","title":"Hong Kong, Taiwan and South Korea","description":"Three centralised, bank-mediated systems for electronic negotiable instruments, each built on a national statute rather than on the MLETR. Hong Kong is the only one whose law belongs to the same family as ours.","sidebar":"tutorialSidebar"},"market/India":{"id":"market/India","title":"India","description":"India\'s law of negotiable instruments, the Negotiable Instruments Act 1881, is a year older than the UK Act ours is drawn under and belongs to the same family. Its electronic infrastructure for bills of exchange is the receivables-discounting system licensed by the central bank; a general law on electronic trade documents was published for comment in 2026.","sidebar":"tutorialSidebar"},"market/Israel":{"id":"market/Israel","title":"Israel","description":"Israel has digitised the clearing of cheques, not the cheque itself. The Bank of Israel has stated what a digital substitute for the paper cheque should do; no such instrument is in use yet.","sidebar":"tutorialSidebar"},"market/Japan":{"id":"market/Japan","title":"Japan","description":"Japan chose not to digitise the bill of exchange. It created a new statutory claim, the electronically recorded monetary claim, kept by designated registries, and is now ending the use of paper promissory notes and cheques altogether.","sidebar":"tutorialSidebar"},"market/Latin-America":{"id":"market/Latin-America","title":"Latin America","description":"Latin America has the most mature live electronic credit instruments outside East Asia: Argentina\'s electronic cheque now carries most of the cheque clearing by value, and Brazil, Colombia and Peru run national registries of electronic trade bills. All are central registries reached through banks or licensed registrars.","sidebar":"tutorialSidebar"},"market/Middle-East":{"id":"market/Middle-East","title":"Middle East","description":"Saudi Arabia runs the clearest example of a state platform for electronic promissory notes; Bahrain and Abu Dhabi Global Market enacted the MLETR early but no bill-of-exchange platform has been reported on their basis; T\xfcrkiye has drafted but, as far as we have found, not enacted an electronic cheque and note law.","sidebar":"tutorialSidebar"},"market/Singapore":{"id":"market/Singapore","title":"Singapore","description":"Singapore was among the first countries to adopt the UNCITRAL Model Law on Electronic Transferable Records and is the home of TradeTrust, the most developed open-source framework for electronic transferable documents. Its bills of exchange law, like ours, descends from the UK Bills of Exchange Act 1882.","sidebar":"tutorialSidebar"},"market/UK":{"id":"market/UK","title":"United Kingdom","description":"The United Kingdom is the jurisdiction whose law our bills are drawn under. Every electronic bill of exchange or promissory note issued in the UK so far has been issued under the same two Acts as ours; the difference lies in what the instrument is and where its register is kept.","sidebar":"tutorialSidebar"},"market/US":{"id":"market/US","title":"United States","description":"United States law has no general electronic bill of exchange. Drafts and notes under Article 3 of the Uniform Commercial Code remain paper instruments; electronic equivalents exist through two separate routes, \\"transferable records\\" for mortgage notes and \\"controllable electronic records\\" under the new Article 12.","sidebar":"tutorialSidebar"},"smart-contract/deployments":{"id":"smart-contract/deployments","title":"Deployments","description":"The current deployment of the contract on each network. This table is generated from the project\'s deployment records at every build of the site, so it always shows the address the site itself uses.","sidebar":"tutorialSidebar"},"smart-contract/functions":{"id":"smart-contract/functions","title":"Functions by role","description":"Amounts are always counted in bills, the smallest units of the token: amount = 1000 means 1000 bills, that is \u20AA10.00. Functions restricted to a party revert when called from any other address; the restriction is enforced by the contract itself, not by this website.","sidebar":"tutorialSidebar"},"smart-contract/how-it-works":{"id":"smart-contract/how-it-works","title":"How it works","description":"The BillsOfExchange smart contract keeps a registry of electronic bills of exchange on Ethereum. It is designed to meet the definition of a bill of exchange in the UK Bills of Exchange Act 1882 and to hold the bills in electronic form under the Electronic Communications Act 2000 and the Electronic Trade Documents Act 2023.","sidebar":"tutorialSidebar"},"tutorial/start":{"id":"tutorial/start","title":"User manual","description":"Under development ...","sidebar":"tutorialSidebar"}}}}')}}]);